export function normalizeCompanyKey(rawCompany?: string): 'MarBR' | 'DZM' | 'G2' {
  if (!rawCompany) return 'MarBR';
  const c = rawCompany.trim().toUpperCase();
  if (c.includes('DZM')) return 'DZM';
  if (c.includes('G2') || c.includes('GRUPO 2') || c.includes('GRUPO2')) return 'G2';
  return 'MarBR';
}

export function getCompanyCreditorInfo(companyName?: string): CompanyCreditorInfo {
  const key = normalizeCompanyKey(companyName);
  return COMPANY_CREDITOR_CONFIG[key] || COMPANY_CREDITOR_CONFIG.MarBR;
}
